    "image": "https://substackcdn.com/image/fetch/$s_!nYda!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F499edfad-a533-4bc2-a0d2-b8ead811fb53_6250x2813.png",
